-- Enhanced email chrome (icon badge per template, mobile media query) applied to all
-- existing templates, plus 7 new templates covering previously-silent events:
-- GitHub connect/sync-failure, account status change, role change, account deletion,
-- portfolio domain change, and automatic testimonial-request invites.

UPDATE notification_templates SET
    subject = 'Your Verification Code — PortfoliosBuilder',
    message_body = '<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><style>@media only screen and (max-width:600px){.email-container{width:100% !important}.email-body{padding:28px 20px !important}}</style></head><body style="margin:0;padding:0;background:#f3f4f6;font-family:-apple-system,Segoe UI,Roboto,sans-serif"><table width="100%" cellpadding="0" cellspacing="0" style="padding:40px 16px"><tr><td align="center"><table class="email-container" width="560" cellpadding="0" cellspacing="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 1px 4px rgba(0,0,0,.08);max-width:560px"><tr><td style="background:linear-gradient(135deg,#059669,#047857);padding:34px 32px;text-align:center"><table cellpadding="0" cellspacing="0" style="margin:0 auto 14px"><tr><td style="width:46px;height:46px;border-radius:13px;background:rgba(255,255,255,0.16);text-align:center;vertical-align:middle;font-size:22px;line-height:46px">&#128272;</td></tr></table><p style="color:#d1fae5;font-size:11px;letter-spacing:2px;margin:0 0 8px;text-transform:uppercase;font-weight:700">PortfoliosBuilder</p><h1 style="color:#fff;font-size:21px;margin:0;font-weight:800">Verify Your Email</h1></td></tr><tr><td class="email-body" style="padding:36px 32px"><p style="color:#374151;font-size:15px;margin:0 0 20px;">Hi <strong>{{fullName}}</strong>,</p><p style="color:#374151;font-size:15px;margin:0 0 20px;">Use the code below to verify your email address. It expires in <strong>{{expiryMinutes}} minutes</strong>.</p><div style="text-align:center;margin:0 0 24px"><div style="display:inline-block;background:#ecfdf5;border:1.5px dashed #059669;border-radius:12px;padding:18px 36px"><span style="font-size:34px;font-weight:800;letter-spacing:10px;color:#047857">{{otp}}</span></div></div><p style="color:#9ca3af;font-size:13px;margin:0;">Did not request this code? You can safely ignore this email.</p></td></tr><tr><td style="padding:20px 32px;border-top:1px solid #f3f4f6;text-align:center"><p style="color:#9ca3af;font-size:12px;margin:0">This is an automated message from PortfoliosBuilder.</p></td></tr></table></td></tr></table></body></html>'
WHERE template = 'OTP-VERIFICATION';

