 16px;border-bottom:1px solid #e5e7eb"><a href="mailto:{{senderEmail}}" style="color:#059669">{{senderEmail}}</a></td></tr><tr><td style="padding:12px 16px;font-weight:600;color:#374151;background:#f9fafb;border-bottom:1px solid #e5e7eb">Phone</td><td style="padding:12px 16px;color:#374151;border-bottom:1px solid #e5e7eb">{{senderPhone}}</td></tr><tr><td style="padding:12px 16px;font-weight:600;color:#374151;background:#f9fafb;vertical-align:top">Message</td><td style="padding:12px 16px;color:#374151">{{message}}</td></tr></table></td></tr><tr><td style="padding:20px 32px;border-top:1px solid #f3f4f6;text-align:center"><p style="color:#9ca3af;font-size:12px;margin:0">Sent via PortfoliosBuilder</p></td></tr></table></td></tr></table></body></html>'
