n:0">{{newMessages}}</p><p style="font-size:13px;color:#6b7280;margin:4px 0 0">New Messages</p></td></tr></table><h3 style="font-size:14px;color:#374151;margin:0 0 12px">Top Traffic Sources</h3><table width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e5e7eb">{{topReferrersHtml}}</table></td></tr><tr><td style="padding:20px 32px;border-top:1px solid #f3f4f6;text-align:center"><p style="color:#9ca3af;font-size:12px;margin:0">To stop receiving these emails, turn off Weekly Digest in your admin profile settings.</p></td></tr></table></td></tr></table></body></html>'
